 5	use DateTimeImmutable;
 6	use Symfony\Component\Yaml\Yaml;
 7	
 8	/**
 9	 * An outlaw status runs for the documented fixed duration from its application. Recalling the mission
10	 * that caused it changes nothing, so the expiry is derived from the application time alone.
11	 */
12	final class OutlawStatusRule
13	{
14	    private const BEHAVIOR_FILE = '/resources/behavior/outlaw.yaml';
15	
16	    public function expiresAt(DateTimeImmutable $appliedAt): DateTimeImmutable
17	    {
18	        $days = (int) Yaml::parseFile(dirname(__DIR__, 3) . self::BEHAVIOR_FILE)['duration_days'];
19	
20	        return $appliedAt->modify('+' . $days . ' days');
21	    }
22	
23	    public function isActive(DateTimeImmutable $appliedAt, DateTimeImmutable $now): bool
24	    {
25	        return $now < $this->expiresAt($appliedAt);
26	    }
27	}

