 7	/**
 8	 * One row of a galaxy view, carried exactly as the host reported it.
 9	 *
10	 * WIK-206: the field semantics come from a community-sourced wiki that the host has not confirmed,
11	 * so this record stays inert. It is a read-only observation, never an input to a decision, and it
12	 * deliberately exposes no derived fleet, resource or combat value — attaching one here would turn a
13	 * raw scan into a de-facto doctrine without the mechanics ever being confirmed.
14	 */
15	final readonly class GalaxyScanObservation
16	{
17	    public function __construct(
18	        private int $galaxy,
19	        private int $system,
20	        private int $position,
21	        private ?string $occupant,
22	        private bool $hasDebris,
23	    ) {
24	    }
25	
26	    public function galaxy(): int
27	    {
28	        return $this->galaxy;
29	    }
30	
31	    public function system(): int
32	    {
33	        return $this->system;
34	    }
35	
36	    public function position(): int
37	    {
38	        return $this->position;
39	    }
40	
41	    /**
42	     * Unparsed as reported: whatever the galaxy view showed for this slot, null when it showed none.
43	     */
44	    public function occupant(): ?string
45	    {
46	        return $this->occupant;
47	    }
48	
49	    public function hasDebris(): bool
50	    {
51	        return $this->hasDebris;
52	    }
53	
54	    /**
55	     * Always false: no field in this row has been confirmed by the host yet, and hard-coding the
56	     * answer keeps a caller from declaring the observation trustworthy on its own.
57	     */
58	    public function isVerified(): bool
59	    {
60	        return false;
61	    }
62	}

