127	    /**
128	     * The largest empty, colonisable coordinate from a seeded start, bounded.
129	     *
130	     * An experienced player colonises the bigger slots, not the first empty one:
131	     * the host's own field range for each position is the planet's size, so the
132	     * walk keeps the largest empty slot it sees and returns it. The per-account
133	     * seed offsets the walk so two accounts do not claim the same slot, and it
134	     * stays the tie-break: an equal-size slot later in the walk loses. The host
135	     * answers reach (`canColonizePosition`) and emptiness (one read of the rows
136	     * occupying the systems the walk visits); the field range is the host's
137	     * `planetData`, never a position list.
138	     */
139	    private function emptySlot(PlayerService $player, int $seed): ?Coordinate
140	    {
141	        $maxScans = $this->maxCoordinateChecks();
142	        $galaxies = max(1, $this->settings->numberOfGalaxies());
143	        $systems = max(1, $this->settings->numberOfSystems());
144	        // The walk is bounded by systems rather than by a running counter: one
145	        // comparison caps the whole decision at the behaviour file's coordinate
146	        // ceiling, so a full universe cannot stall a session and the bound never
147	        // needs a per-check branch.
148	        $systemsPerGalaxy = min($systems, max(1, intdiv($maxScans, 12 * $galaxies)));
149	
150	        $best = null;
151	        $bestFields = -1.0;
152	
153	        for ($galaxyOffset = 0; $galaxyOffset < $galaxies; $galaxyOffset++) {
154	            $galaxy = 1 + (($seed + $galaxyOffset) % $galaxies);
155	
156	            $systemsInWalk = [];
157	            for ($system = 1; $system <= $systemsPerGalaxy; $system++) {
158	                $systemsInWalk[] = 1 + (($system + ($seed >> 4) - 1) % $systems);
159	            }
160	
161	            // The walk asks about every position of every system it visits, and a
162	            // point lookup per position costs a round trip each for an answer one
163	            // read already holds. `destroyed` is deliberately unfiltered: a row
164	            // occupies its coordinate exactly as the host reports it.
165	            $occupied = [];
166	            foreach (Planet::query()
167	                ->where('galaxy', $galaxy)
168	                ->whereIn('system', $systemsInWalk)
169	                ->where('planet_type', PlanetType::Planet->value)
170	                ->get(['system', 'planet']) as $occupying) {
171	                $occupied[$occupying->system . ':' . $occupying->planet] = true;
172	            }
173	
174	            foreach ($systemsInWalk as $systemWithOffset) {
175	                for ($position = UniverseConstants::MIN_PLANET_POSITION; $position <= UniverseConstants::MAX_PLANET_POSITION; $position++) {
176	                    if (!$player->canColonizePosition($position)) {
177	                        continue;
178	                    }
179	
180	                    if (isset($occupied[$systemWithOffset . ':' . $position])) {
181	                        continue;
182	                    }
183	
184	                    // The size a planet at this position would get, from the host's
185	                    // own field range (mid positions report the widest range). The
186	                    // largest empty slot seen so far wins; strict > keeps the
187	                    // seeded walk order as the tie-break.
188	                    $fields = $this->planetServiceFactory->planetData($position, false)['fields'][1];
189	                    if ($fields > $bestFields) {
190	                        $best = new Coordinate($galaxy, $systemWithOffset, $position);
191	                        $bestFields = (float) $fields;
192	                    }
193	                }
194	            }
195	        }
196	
197	        return $best;
198	    }
199	}

