```php
<?php

namespace Modules\AI\Domain\Intel;

use Illuminate\Support\Facades\DB;
use Symfony\Component\Yaml\Yaml;

/**
 * What a target has paid the account before: a bounded counter per player and coordinate, raised by a
 * profitable raid and lowered by one that came home empty (architecture step 7, 4.2).
 *
 * The counter is memory, not a forecast: it never touches the host's world, it outlives the process in
 * `ai_intel`, and every bound it runs on is read by name from `resources/behavior/intel.yaml`, so a host
 * retunes how forgiving the account is without an edit here.
 */
final class IntelBook
{
    private const POLICY_FILE = '/resources/behavior/intel.yaml';

    /** @var array<string, mixed>|null */
    private static ?array $policy = null;

    /** The coordinate key the book is written and read under, from the three numbers a report carries. */
    public static function key(int $galaxy, int $system, int $position): string
    {
        return $galaxy . ':' . $system . ':' . $position;
    }

    public function priority(int $playerId, string $coordinate): int
    {
        $priority = DB::table('ai_intel')
            ->where('player_id', $playerId)
            ->where('coordinate', $coordinate)
            ->value('priority');

        return $priority === null ? 0 : (int) $priority;
    }

    /**
     * A raid's outcome at one target, folded into its counter: a win raises it, a loss lowers it, and
     * the bound stops either from running away.
     */
    public function recordOutcome(int $playerId, string $coordinate, bool $won): int
    {
        $step = $won ? $this->int('target_priority.win_step', 1) : -$this->int('target_priority.loss_step', 1);
        $priority = $this->bounded($this->priority($playerId, $coordinate) + $step);

        DB::table('ai_intel')->updateOrInsert(
            ['player_id' => $playerId, 'coordinate' => $coordinate],
            ['priority' => $priority, ($won ? 'wins' : 'losses') => ...],
        );
    }
}
```

