```php
<?php

namespace Modules\AI\Domain\Intel;

use Illuminate\Support\Facades\DB;
use Symfony\Component\Yaml\Yaml;

/**
 * What the account remembers about a target: a bounded counter per player and coordinate, raised by a
 * raid that came home with loot and lowered by one that came home empty (architecture step 7, 4.2).
 *
 * It is memory, not a forecast. Nothing here reads the host's world and nothing is derived from a live
 * foreign planet: the only writer is the account's own raid outcome, and the only reader is the raid
 * decision that asks whether this planet has ever paid. The bound that keeps the counter from running
 * away, and the step each outcome moves it by, are read by name from
 * `resources/behavior/intel.yaml`, so a host retunes how forgiving the account is without an edit here.
 */
final class IntelBook
{
    private const POLICY_FILE = '/resources/behavior/intel.yaml';

    /** @var array<string, mixed>|null */
    private static ?array $policy = null;

    /** The key a target is written and read under: the three numbers every report and mission carries. */
    public static function key(int $galaxy, int $system, int $position): string
    {
        return $galaxy . ':' . $system . ':' . $position;
    }

    /** The current score of a target: zero for one the account has never fought. */
    public function priority(int $playerId, string $coordinate): int
    {
        $priority = DB::table('ai_intel')
            ->where('player_id', $playerId)
            ->where('coordinate', $coordinate)
            ->value('priority');

        return $priority === null ? 0 : (int) $priority;
    }

    /**
     * Fold one raid outcome into the target's counter: a profitable raid raises it, a loss lowers it,
     * and the counter stops at the bound either way. Returns the counter as it now stands.
     */
    public function recordOutcome(int $playerId, string $coordinate, bool $won): int
    {
        $priority = $this->bounded($this->priority($playerId, $coordinate) + ($won ? $this->step('win_step') : -$this->step('loss_step')));
        $row = DB::table('ai_intel')->where('player_id', $playerId)->where('coordinate', $coordinate)->first(['outcomes']);

        if ($row === null) {
            DB::table('ai_intel')->insert([
                'player_id' => $playerId,
                'coordinate' => $coordinate,
                'priority' => $priority,
                'outcomes' => 1,
                'last_outcome_at' => now(),
                'created_at' => now(),
                'updated_at' => now(),
            ]);

            return $priority;
        }

        DB::table('ai_intel')->where('player_id', $playerId)->where('coordinate', $coordinate)->update([
            'priority' => $priority,
            'outcomes' => (int) $row->outcomes + 1,
            'last_outcome_at' => now(),
            'updated_at' => now(),
        ]);

        return $priority;
    }

    /** The counter's floor: at or below it the target has cost the account more than it ever paid. */
    public function priorityFloor(): int
    {
        return $this->int('target_priority.floor', 0);
    }

    private function step(string $name): int
    {
        return max(1, $this->int('target_priority.' . $name, 1));
    }

    private function bounded(int $priority): int
    {
        return max($this->priorityFloor(), min($this->int('target_priority.ceiling', $priority), $priority));
    }

    private function int(string $path, int $fallback): int
    {
        $value = self::$policy ??= $this->load();

        foreach (explode('.', $path) as $segment) {
            $value = is_array($value) ? ($value[$segment] ?? null) : null;
        }

        return is_numeric($value) ? (int) $value : $fallback;
    }

