 33	        private PlanetServiceFactory $planetServiceFactory,
 34	        private ActivityIntelReader $activityIntelReader,
 35	    ) {
 36	    }
 37	
 38	    public function handle(int $playerId, int $originPlanetId, int $targetGalaxy, int $targetSystem, int $targetPosition, int $targetType, ?array $launchUnits = null): AiActionResult
 39	    {
 40	        if (!Planet::query()->whereKey($originPlanetId)->where('user_id', $playerId)->exists()) {
 41	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 42	        }
 43	
 44	        try {
 45	            $player = $this->playerGameStateService->advance($playerId, $originPlanetId);
 46	
 47	            if ($player->isBanned()) {
 48	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 49	            }
 50	            if ($player->isInVacationMode()) {
 51	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 52	            }
 53	
 54	            $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 55	
 56	            $targetCoordinate = new Coordinate($targetGalaxy, $targetSystem, $targetPosition);
 57	
 58	            // Between planning and dispatch the target may have logged in. The
 59	            // activity star is galaxy-visible, so flying into a just-touched
 60	            // target is a recall or a ninja, not a raid (RAID-010).
 61	            $target = $this->planetServiceFactory->makeForCoordinate($targetCoordinate, false, PlanetType::from($targetType));
 62	            if ($target !== null && $this->activityIntelReader->activityAt($target)) {
 63	                return AiActionResult::rejected(AiQueueActionReason::TargetActiveAtDispatch);
 64	            }
 65	
 66	            // A moon active while its planet is quiet is the defender moving a
 67	            // fleet on the moon — staging the trap a raid would fly into
 68	            // (NIN-005). Flying into it is a ninja, not a raid.
 69	            $moon = $this->planetServiceFactory->makeMoonForCoordinate($targetCoordinate);
 70	            if ($moon !== null && $target !== null && $this->activityIntelReader->moonOnlyActivity($moon, $target)) {
 71	                return AiActionResult::rejected(AiQueueActionReason::TargetStagingAtDispatch);
 72	            }
 73	
 74	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 75	            $fleet = $this->launchFleet($origin, $launchUnits);
 76	
 77	            // The host refuses a flight the origin cannot pay the fuel for; spending deuterium on
 78	            // mines or ferries between planning and dispatch is how a planned raid ends up here.
 79	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $targetCoordinate, 0, 10.0);
 80	            if ($fuel > floor($origin->deuterium()->get())) {
 81	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 82	            }
 83	            // The host refuses a flight the fleet's own tanks cannot hold the fuel for ("insufficient
 84	            // storage capacity"); a long route flown by a small subset is how a planned raid ends up here.
 85	            if ($fuel > $fleet->getTotalFuelCapacity($player)) {
 86	                return AiActionResult::rejected(AiQueueActionReason::FuelTankShort);
 87	            }
 88	
 89	            $mission = $fleetMissions->createNewFromPlanet(
 90	                $origin,
 91	                $targetCoordinate,
 92	                PlanetType::from($targetType),
 93	                AttackMission::getTypeId(),
 94	                $fleet,
 95	                new Resources(),
 96	                10,
 97	            );
 98	
 99	            return AiActionResult::queued($mission->id);
100	        } catch (Exception $exception) {
101	            return AiActionResult::rejected($exception->getMessage());
102	        }
103	    }
104	
105	    /**
106	     * The fleet the raid flies: the counter-selected subset, or the whole origin fleet when the
107	     * intent carried no subset (an older work item). The host still owns what the planet holds.
108	     *
109	     * @param array<string, int>|null $launchUnits
110	     */
111	    private function launchFleet(PlanetService $origin, ?array $launchUnits): UnitCollection
112	    {
113	        if ($launchUnits === null || $launchUnits === []) {
114	            return $origin->getShipUnits();
115	        }
116	
117	        $fleet = new UnitCollection();
118	        foreach ($launchUnits as $machineName => $amount) {
119	            if ($amount > 0) {
120	                $fleet->addUnit(ObjectService::getUnitObjectByMachineName($machineName), $amount);
121	            }
122	        }
123	
124	        return $fleet->units === [] ? $origin->getShipUnits() : $fleet;
125	    }
126	}

