 8	/**
 9	 * The subset of a fleet that can actually fly.
10	 *
11	 * Solar satellites are ship objects with speed zero and never leave orbit, but
12	 * the host's getShipUnits() returns them alongside the movable hulls. The host's
13	 * flight math divides by the slowest ship's speed, so a stationary hull left in
14	 * the collection makes calculateFleetMissionDuration divide by zero. Every
15	 * flight-time or fuel quote is therefore priced on the hulls that can move.
16	 */
17	final class MovableFleet
18	{
19	    public static function of(PlayerService $player, UnitCollection $units): UnitCollection
20	    {
21	        $movable = new UnitCollection();
22	
23	        foreach ($units->units as $entry) {
24	            if ($entry->unitObject->properties->speed->calculate($player)->totalValue > 0) {
25	                $movable->addUnit($entry->unitObject, $entry->amount);
26	            }
27	        }
28	
29	        return $movable;
30	    }
