21	     * Creates a planet for the given user at a collision-safe coordinate.
22	     *
23	     * Uses a DB-existence check and defaults to positions 13-15 (outside the allocator's
24	     * assigned range of 4-12) so that this planet never collides with a home planet placed
25	     * by the allocator during registration — even when two test users land in the same system.
26	     *
27	     * @param int $userId The user_id to assign the new planet to.
28	     * @param int $minPosition Lower bound for position search (default 13).
29	     * @param int $maxPosition Upper bound for position search (default 15).
30	     * @param int $minSystemDistance Minimum system offset from the current player's planet (default 0 = any system).
31	     */
32	    protected function createPlanetAtSafeCoordinate(int $userId, int $minPosition = 13, int $maxPosition = 15, int $minSystemDistance = 0): PlanetService
33	    {
34	        $coordinate = $this->getNearbyEmptyCoordinate($minPosition, $maxPosition, $minSystemDistance);
35	
36	        $planet = Planet::factory()->create([
37	            'user_id' => $userId,
